/**
 * socTickets — casos SIMULADOS del simulador SOC / Blue Team
 * (empresa ficticia Nexora S.A., SOC "Blue Team" — material de estudio,
 * no datos reales). 50 casos: 20 generales (soc-001..soc-020) + 30 del
 * Proyecto Final "Primera Semana en el SOC" (soc-021..soc-050, 6 por día
 * × 5 días). Se siembran en la tabla Dexie `socTickets` (v23) de forma
 * idempotente por id + dismissal.
 *
 * Reglas de contenido (NON-NEGOTIABLE):
 *  - NO inventar Event IDs, comandos, KQL/SPL, MITRE ATT&CK ni IoCs
 *    plausibles-falsos: todo lo técnico debe ser real y verificable.
 *  - Idioma: campos descriptivos en es-CO; queries/comandos tal cual se
 *    ejecutan (inglés técnico).
 *  - El "requester" es el origen del caso: SIEM (Sentinel/Splunk), EDR
 *    (Defender), usuario (reporte), mesa de service desk, o auditoría.
 */
import type { SocTicketLevel, SocTicketPriority, SocTicketType, SocEnvironment } from '../types';

