    "id": "soc-028",
    "number": "SOC-3028",
    "title": "Día 2: push bombing contra la directora financiera en la madrugada",
    "category": "SOC - Identity / Ataques de Contraseña",
    "subcategory": "Primera semana SOC — Día 2 (Identity)",
